# Loop until we find a downloaded song
max_iterations = 100
for i in range(max_iterations):
    current = apis.spotify.show_current_song(access_token=access_token)
    if current['song_id'] in downloaded_ids:
        print(f"Found downloaded song: {current['song_id']} - {current['title']}")
        break
    else:
        print(f"Song {current['song_id']} not downloaded, skipping")
        next_result = apis.spotify.next_song(access_token=access_token)
        print(next_result)
else:
    print("No downloaded song found after max iterations")

