# Correct the variable name and search for all songs
found_songs = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_access_token, page_limit=20)
    # Find exact match
    match = None
    for result in results:
        if result['title'].lower() == song['title'].lower():
            # Check if any artist matches
            for artist in result['artists']:
                if artist['name'].lower() == song['artist'].lower():
                    match = result
                    break
            if match:
                break
    if match:
        found_songs.append({'song_id': match['song_id'], 'title': song['title'], 'artist': song['artist']})
        print(f"Found: {song['title']} by {song['artist']} -> song_id {match['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal found: {len(found_songs)} out of {len(songs_to_archive)}")

