    results = apis.spotify.search_songs(query=query, access_token=spotify_access_token, page_limit=20)
    found = None
    for item in results:
        # Check if title matches (case-insensitive) and artist matches
        if item['title'].lower() == song['title'].lower():
            # Check if any artist matches
            for artist in item['artists']:
                if artist['name'].lower() == song['artist'].lower():
                    found = item
                    break
            if found:
                break
    if found:
        archive_song_ids.append(found['song_id'])
