# Playlist data from previous step (we have it in the output, but we'll re-fetch to be safe)
playlist_ids = [513, 514, 515, 516, 517, 518, 519]
for pid in playlist_ids:
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    songs = pl.get('songs', [])
    song_ids_in_pl = [s['id'] for s in songs]
    for sid in target_song_ids:
        if sid in song_ids_in_pl:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=sid, access_token=spotify_token)
            print(f"Removed song {sid} from playlist {pid}: {result}")

